import java.util.List;

interface Fruit { int grams(); }
record Apple(int grams) implements Fruit {}

// Java can't say "T only comes out" on the declaration
interface Dispenser<T> {
    T next();
}

class Dispensers {
    // every method that should accept subtypes must remember ? extends
    static int total(Dispenser<? extends Fruit> dispenser, int n) {
        int sum = 0;
        for (int i = 0; i < n; i++) sum += dispenser.next().grams();
        return sum;
    }

    static int sum(List<? extends Fruit> fruit) {
        return fruit.stream().mapToInt(Fruit::grams).sum();
    }

    // forget it once, and the method is stricter than it needs to be
    static int strict(Dispenser<Fruit> dispenser) { return dispenser.next().grams(); }
}

