class Dispenser<T>(items: List<T>) {
    private val queue = ArrayDeque(items)
    var lastServed: T? = null
        private set

    fun hasNext(): Boolean = queue.isNotEmpty()
    fun next(): T { val item = queue.removeFirst(); lastServed = item; return item }
    fun nextOr(fallback: T): T = if (queue.isEmpty()) fallback else next()
}

