class Dispenser<T> {
    private final ArrayDeque<T> queue;
    private T lastServed;

    Dispenser(List<T> items) { queue = new ArrayDeque<>(items); }

    boolean hasNext() { return !queue.isEmpty(); }
    T next() { T item = queue.removeFirst(); lastServed = item; return item; }
    T nextOr(T fallback) { return queue.isEmpty() ? fallback : next(); }
    T lastServed() { return lastServed; }
}

